from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    mode = draw(st.integers(0, 3))
    if mode == 0:
        h = list(range(1, n + 1))
    elif mode == 1:
        h = list(range(n, 0, -1))
    else:
        h = draw(st.permutations(list(range(1, n + 1))))
    return f"{n}\n{' '.join(map(str, h))}\n"

def validate(inp):
    t = inp.split()
    if len(t) < 1:
        return False
    n = int(t[0])
    if not (1 <= n <= 2 * 10**5):
        return False
    if len(t) != n + 1:
        return False
    h = [int(x) for x in t[1:]]
    if len(set(h)) != n:
        return False
    return all(1 <= x <= n for x in h)

def ref(inp):
    t = inp.split()
    n = int(t[0])
    h = [int(x) for x in t[1:1 + n]]
    res = []
    for i in range(n):
        cnt = 0
        between_max = 0  # max height strictly between i and current j
        for j in range(i + 1, n):
            if between_max < h[j]:
                cnt += 1
            between_max = max(between_max, h[j])
        res.append(cnt)
    return " ".join(map(str, res))
